package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.service.BlockedIdentityService;import jakarta.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class SafetyControlsTest {
 @Autowired com.dating.backend.service.FraudDetectionService fraud;@Autowired EntityManager em;@Autowired SocialService social;@Autowired BlockedIdentityService blocked;@Autowired DailyMatchSchedule schedule;
 User a;List<User> targets=new ArrayList<>();
 @BeforeEach void setup(){a=person("source");var w=new CreditWallet();w.setUserId(a.getId());w.setBalance(100);em.persist(w);for(int i=0;i<8;i++){var u=person("target"+i);targets.add(u);var c=new DailyMatchCard();c.setOwnerId(a.getId());c.setCandidateId(u.getId());c.setCycleDay(schedule.current().day());c.setSlot(i);c.setRevealedAt(Instant.now());em.persist(c);}}
 User person(String name){var u=User.builder().email(UUID.randomUUID()+"@safety.test").nickname(name).provider("LOCAL").status("ACTIVE").build();em.persist(u);return u;}
 SocialService.DirectRequest req(int i,String text,boolean ack){return new SocialService.DirectRequest(targets.get(i).getId(),text,UUID.randomUUID().toString(),10,ack);}
 @Test void profileScoreDoesNotAutomaticallySuspend(){em.persist(UserProfile.builder().userId(a.getId()).region("서울 강남구").introduction("투자 코인 송금 관련 업무를 합니다").build());fraud.evaluateUserProfile(a.getId());assertEquals("ACTIVE",a.getStatus());assertTrue(a.getFraudRiskScore()>=60);assertEquals("HIGH_RISK",a.getFraudReviewStatus());}
 @Test void sevenRequestsAllowedEighthDoesNotChargeAndRefundDoesNotReset(){for(int i=0;i<7;i++){var opened=social.direct(a.getEmail(),req(i,"안녕하세요",false));social.decide(targets.get(i).getEmail(),opened.roomId(),false);}assertEquals(100,em.find(CreditWallet.class,a.getId()).getBalance());var ex=assertThrows(ResponseStatusException.class,()->social.direct(a.getEmail(),req(7,"안녕하세요",false)));assertEquals(429,ex.getStatusCode().value());assertEquals(7,em.createQuery("select count(r) from DirectChatRequest r where r.senderId=:u",Long.class).setParameter("u",a.getId()).getSingleResult());assertEquals(100,em.find(CreditWallet.class,a.getId()).getBalance());}
 @Test void olderRequestsDoNotConsumeTodaysQuota(){for(int i=0;i<7;i++){var room=social.direct(a.getEmail(),req(i,"안녕하세요",false));em.find(DirectChatRequest.class,room.roomId()).setExpiresAt(Instant.now().minus(Duration.ofDays(1)));}assertDoesNotThrow(()->social.direct(a.getEmail(),req(7,"안녕하세요",false)));}
 @Test void linkRequiresAcknowledgementAndRecipientGetsWarning(){var unack=req(0,"투자 정보 https://example.com",false);var ex=assertThrows(ResponseStatusException.class,()->social.direct(a.getEmail(),unack));assertTrue(ex.getReason().startsWith("SAFETY_WARNING:"));assertEquals(100,em.find(CreditWallet.class,a.getId()).getBalance());assertEquals(0,em.createQuery("select count(r) from ChatRoom r",Long.class).getSingleResult());var ack=new SocialService.DirectRequest(unack.targetId(),unack.text(),unack.clientId(),10,true);var opened=social.direct(a.getEmail(),ack);assertNotNull(social.messages(targets.get(0).getEmail(),opened.roomId(),0,0).messages().get(0).safetyWarning());assertEquals(0,social.direct(a.getEmail(),ack).charged());}
 @Test void financialAndObfuscatedUrlSignalsButOrdinaryChatNotFlagged(){assertFalse(MessageSafety.flags("https://example.com").isEmpty());assertFalse(MessageSafety.flags("ｈｔｔｐｓ：／／example.com").isEmpty());assertFalse(MessageSafety.flags("www.exa\u200bmple.com").isEmpty());assertFalse(MessageSafety.flags("가상자산 투자 송금").isEmpty());assertTrue(MessageSafety.flags("오늘 산책 어때요?").isEmpty());}
 @Test void permanentAndTemporarySanctionsFollowExactExpiryAndGoogleUid(){a.setFirebaseUid("blocked-uid");a.setSanctionType("PERMANENT");assertThrows(ResponseStatusException.class,()->blocked.validateSanction(a.getEmail(),null));assertThrows(ResponseStatusException.class,()->blocked.validateSanction("different@example.com","blocked-uid"));a.setSanctionType("TEMPORARY");a.setSuspendedUntil(Instant.now().plusSeconds(60));assertThrows(ResponseStatusException.class,()->blocked.validateSanction(a.getEmail(),null));a.setSuspendedUntil(Instant.now().minusSeconds(1));assertDoesNotThrow(()->blocked.validateSanction(a.getEmail(),null));}
}
